public struct FfiConverterTypeAuthState: FfiConverterRustBuffer {
    typealias SwiftType = AuthState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AuthState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .loggedOut
        
        case 2: return .pending(url: try FfiConverterString.read(from: &buf), code: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .loggedIn(username: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .failed(reason: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AuthState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .loggedOut:
            writeInt(&buf, Int32(1))
        
        
        case let .pending(url,code):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(url, into: &buf)
            FfiConverterString.write(code, into: &buf)
            
        
        case let .loggedIn(username):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(username, into: &buf)
            
        
        case let .failed(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


